import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";import"./chunks/assets.B25yjHWQ.js";var i=JSON.parse(`{"title":"必备软件","description":"windows必备","frontmatter":{"title":"必备软件","description":"windows必备","date":"2026-05-29T00:00:00.000Z","category":"生活指南","tags":["生产力"]},"headers":[],"relativePath":"articles/life/productivity/windows_software.md","filePath":"articles/life/productivity/windows_software.md","articleMeta":{"updated":"2026-05-29","words":2149,"minutes":5}}`),a={name:`articles/life/productivity/windows_software.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h2 id="写博客套装" tabindex="-1">写博客套装 <a class="header-anchor" href="#写博客套装" aria-label="Permalink to “写博客套装”">​</a></h2><h3 id="_1-typora" tabindex="-1">1. Typora <a class="header-anchor" href="#_1-typora" aria-label="Permalink to “1. Typora”">​</a></h3><p><a href="https://typoraio.cn/" target="_blank" rel="noreferrer">https://typoraio.cn/</a></p><p>Markdown文档处理，图片自动上传/处理。</p><h3 id="_2-github-desktop" tabindex="-1">2. Github Desktop <a class="header-anchor" href="#_2-github-desktop" aria-label="Permalink to “2. Github Desktop”">​</a></h3><p><a href="https://desktop.github.com/download/" target="_blank" rel="noreferrer">https://desktop.github.com/download/</a></p><p>Git 工具，将静态网站托管到Github</p><h3 id="_3-picgo" tabindex="-1">3.PICGO <a class="header-anchor" href="#_3-picgo" aria-label="Permalink to “3.PICGO”">​</a></h3><p><a href="https://github.com/Molunerfinn/PicGo/releases" target="_blank" rel="noreferrer">https://github.com/Molunerfinn/PicGo/releases</a></p><p>考虑到博客越写越多，图片存储到腾讯云对象云存储（COS）。通过PICGO可以搭配Typora自动上传图片至腾讯云COS。</p><h2 id="网络服务" tabindex="-1">网络服务 <a class="header-anchor" href="#网络服务" aria-label="Permalink to “网络服务”">​</a></h2><h3 id="_1-chrome浏览器" tabindex="-1">1.Chrome浏览器 <a class="header-anchor" href="#_1-chrome浏览器" aria-label="Permalink to “1.Chrome浏览器”">​</a></h3><p><a href="https://www.google.com/intl/zh-CN/chrome/" target="_blank" rel="noreferrer">https://www.google.com/intl/zh-CN/chrome/</a></p><p>Windows自带的Edge或者Mac自带的Safari已经足够好用。Chrome浏览器主要是因为保存了各类网站密码。</p><h3 id="_2-fl-clash代理工具" tabindex="-1">2.FL Clash代理工具 <a class="header-anchor" href="#_2-fl-clash代理工具" aria-label="Permalink to “2.FL Clash代理工具”">​</a></h3><p><a href="https://github.com/chen08209/FlClash/releases" target="_blank" rel="noreferrer">https://github.com/chen08209/FlClash/releases</a></p><p>A multi-platform proxy client based on ClashMeta,simple and easy to use, open-source and ad-free.</p><p>Multi-platform: Android, Windows, macOS and Linux</p><h3 id="_3-流量-网速监控" tabindex="-1">3. 流量/网速监控 <a class="header-anchor" href="#_3-流量-网速监控" aria-label="Permalink to “3. 流量/网速监控”">​</a></h3><p><a href="https://github.com/zhongyang219/TrafficMonitor" target="_blank" rel="noreferrer">https://github.com/zhongyang219/TrafficMonitor</a></p><p>Traffic Monitor是一款用于Windows平台的网速监控悬浮窗软件，可以显示当前网速、CPU及内存利用率，支持嵌入到任务栏显示，支持更换皮肤、历史流量统计等功能。</p><p>我很需要看目前的实时网速，它可以嵌入任务栏，非常美观且方便。</p><p><img src="/images/image-20260419165216158.webp" alt="image-20260419165216158" width="1000" height="189"></p><h2 id="软件管理" tabindex="-1">软件管理 <a class="header-anchor" href="#软件管理" aria-label="Permalink to “软件管理”">​</a></h2><h3 id="_1-geek-卸载器" tabindex="-1">1.Geek 卸载器 <a class="header-anchor" href="#_1-geek-卸载器" aria-label="Permalink to “1.Geek 卸载器”">​</a></h3><p><a href="https://geekuninstaller.com/" target="_blank" rel="noreferrer">https://geekuninstaller.com/</a></p><p>干净地卸载软件，清除残留。</p><h3 id="_2-火绒" tabindex="-1">2. 火绒 <a class="header-anchor" href="#_2-火绒" aria-label="Permalink to “2. 火绒”">​</a></h3><p><a href="https://www.huorong.cn/" target="_blank" rel="noreferrer">https://www.huorong.cn/</a></p><p>很多人说火绒的杀毒能力不行。但是用来管理开机启动项、右键菜单等，当作电脑管家是当之无愧的。静默不打扰。注意很多仿冒软件，一定要访问官网下载。</p><h3 id="_3-steam-游戏" tabindex="-1">3. Steam-游戏 <a class="header-anchor" href="#_3-steam-游戏" aria-label="Permalink to “3. Steam-游戏”">​</a></h3><p><a href="https://store.steampowered.com/" target="_blank" rel="noreferrer">https://store.steampowered.com/</a></p><p>下载正版游戏。Steam的仿冒软件太多了。注意访问官网。</p><h2 id="实用工具" tabindex="-1">实用工具 <a class="header-anchor" href="#实用工具" aria-label="Permalink to “实用工具”">​</a></h2><h3 id="_1-抢票软件bypass" tabindex="-1">1.抢票软件Bypass <a class="header-anchor" href="#_1-抢票软件bypass" aria-label="Permalink to “1.抢票软件Bypass”">​</a></h3><p><a href="https://www.bypass.cn/" target="_blank" rel="noreferrer">https://www.bypass.cn/</a></p><p>分流抢票是一款完全免费的抢票软件，全程自动抢票、自动抢候补、整点抢预售、稳定捡漏。支持多天、多车次、多席别、多乘客、多站查询、多任务等功能，支持各种提醒、选座和选铺、改签刷票、增开监控，自动支付等</p><h2 id="_2-压缩软件7-zip" tabindex="-1">2.压缩软件7-zip <a class="header-anchor" href="#_2-压缩软件7-zip" aria-label="Permalink to “2.压缩软件7-zip”">​</a></h2><p><a href="https://www.7-zip.org/" target="_blank" rel="noreferrer">https://www.7-zip.org/</a></p><p>中文站：<a href="https://sparanoid.com/lab/7z/" target="_blank" rel="noreferrer">https://sparanoid.com/lab/7z/</a></p><h2 id="避雷-黑名单内的立即卸载" tabindex="-1">避雷-黑名单内的立即卸载 <a class="header-anchor" href="#避雷-黑名单内的立即卸载" aria-label="Permalink to “避雷-黑名单内的立即卸载”">​</a></h2><h3 id="_1-搜狗输入法" tabindex="-1">1.搜狗输入法 <a class="header-anchor" href="#_1-搜狗输入法" aria-label="Permalink to “1.搜狗输入法”">​</a></h3><p>近期，火绒的一篇文章“<a href="https://www.huorong.cn/document/tech/vir_report/1845" target="_blank" rel="noreferrer">搜狗输入法云控下发模块，“暗中”篡改浏览器配置</a>”揭露了搜狗输入法的邪恶嘴脸，搜狗输入法通过技术手段，结合用户画像：例如所在地区、时间等诸多维度进行精准推送，首先检测用户设备上的杀毒软件，随后通过篡改配置文件的方式，强制修改 Edge 与 Chrome 两款主流浏览器的主页及默认搜索引擎设置。</p><p>这间接证明了搜狗将用户输入内容等隐私内容上传至云端，再通过窃取来的隐私塑造用户画像，最终为用户“量身定制”一套搜索引擎和广告推销，导向其灰色产业收入。</p><p>搜狗对此的回应简直是不要脸！</p><p><img src="/images/image-kWZG.webp" alt="img" width="1540" height="808"></p><h3 id="_2-360全家桶" tabindex="-1">2.360全家桶 <a class="header-anchor" href="#_2-360全家桶" aria-label="Permalink to “2.360全家桶”">​</a></h3><p>一人得道，鸡犬升天。很快你的电脑就变成360的摇钱树，开机广告、屏保广告、链接劫持、文件劫持，不是肉鸡，胜似肉鸡。</p><h3 id="_3-百度网盘" tabindex="-1">3.百度网盘 <a class="header-anchor" href="#_3-百度网盘" aria-label="Permalink to “3.百度网盘”">​</a></h3><p>劫持系统。劫持篡改了电脑的看图软件。详见<a href="https://www.landiannews.com/archives/110368.html" target="_blank" rel="noreferrer">百度网盘被发现安装智能看图插件劫持图片打开方式 整个界面还是抄微软的</a></p>`,50)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};